content:
default:
                                                LM_ERR("unexpected char [%c] in status %d: [%.*s] .\n",
                                                                *tmp, status, (int)(tmp - buffer), buffer);
                                                goto error;
                                }
                                break;
                        case ';':
                                switch(status) {
                                        case DISPLAY_QUOTED:
                                        case URI_ENCLOSED:
                                                break;
                                        case URI_OR_TOKEN:
                                                foo = tmp;
                                        case MAYBE_URI_END:
                                                to_b->uri.len = foo - to_b->uri.s;
                                        case END:
                                                to_b->body.len = tmp - to_b->body.s;
                                                tmp = parse_to_param(
                                                                tmp, end, to_b, allow_comma_sep, &saved_status);
                                                goto endofheader;
                                        case F_CRLF:
                                        case F_LF:
                                        case F_CR:
                                                /*previous=crlf and now !=' '*/
                                                goto endofheader;
                                        default:
                                                LM_ERR("unexpected char [%c] in status %d: [%.*s] .\n",
                                                                *tmp, status, (int)(tmp - buffer), buffer);
                                                goto error;
                                }
                                break;
                        case ',':
                                if(allow_comma_sep) {
                                        switch(status) {
                                                case DISPLAY_QUOTED:
                                                case URI_ENCLOSED:
                                                        break;
                                                case URI_OR_TOKEN:
                                                        foo = tmp;
                                                case MAYBE_URI_END:
                                                        to_b->uri.len = foo - to_b->uri.s;
                                                case END:
                                                        to_b->body.len = tmp - to_b->body.s;
                                                        saved_status = END;
                                                        goto endofheader;
                                                case F_CRLF:
                                                case F_LF:
                                                case F_CR:
                                                        /*previous=crlf and now !=' '*/
                                                        goto endofheader;
                                                default:
                                                        LM_ERR("unexpected char [%c] in status %d: [%.*s] "
                                                                        ".\n",
                                                                        *tmp, status, (int)(tmp - buffer), buffer);
                                                        goto error;
                                        }
                                        break;
                                }
                        /* If commas not allowed treat as a default character */
                        default:
                                switch(status) {
                                        case START_TO:
                                                to_b->uri.s = to_b->body.s = tmp;
                                                status = URI_OR_TOKEN;
                                                to_b->display.s = tmp;
                                                break;
                                        case S_URI_ENCLOSED:
                                                to_b->uri.s = tmp;
                                                status = URI_ENCLOSED;
                                                break;
                                        case MAYBE_URI_END:
                                        case DISPLAY_TOKEN_SP:
                                                status = DISPLAY_TOKEN;
                                        case DISPLAY_QUOTED:
                                        case DISPLAY_TOKEN:
                                        case URI_ENCLOSED:
                                        case URI_OR_TOKEN:
                                                break;
                                        case F_CRLF:
                                        case F_LF:
                                        case F_CR:
                                                /*previous=crlf and now !=' '*/
                                                goto endofheader;
                                        default:
                                                LM_DBG("spitting out [%c] in status %d\n", *tmp,
                                                                status);
                                                goto error;
                                }
                } /*char switch*/
        }        /*for*/

        /* Reached end of buffer */
        switch(status) {
                case URI_OR_TOKEN:
                case MAYBE_URI_END:
                case END:
                        saved_status = status;
                        foo = tmp;
        }

endofheader:
        if(to_b->display.len == 0)
                to_b->display.s = 0;
        status = saved_status;
        LM_DBG("end of header reached, state=%d\n", status);
        /* check if error*/
        switch(status) {
                case URI_OR_TOKEN:
                case MAYBE_URI_END:
                        to_b->uri.len = foo - to_b->uri.s;
                case END:
                        to_b->body.len = tmp - to_b->body.s;
                case E_PARA_VALUE:
                        break;
                default:
                        LM_ERR("invalid To -  unexpected "
                                        "end of header in state %d\n",
                                        status);
                        goto error;
        }
        return tmp;

error:
        free_to_params(to_b);
        to_b->error = PARSE_ERROR;
        return tmp;
}


void free_to_params(struct to_body *const tb)
{
        struct to_param *tp = tb->param_lst;
        struct to_param *foo;
        while(tp) {
                foo = tp->next;
                pkg_free(tp);
                tp = foo;
        }
        tb->param_lst = NULL;
}


void free_to(struct to_body *const tb)
{
        free_to_params(tb);
        pkg_free(tb);
}
